                /**
                 * Prevzeti cestek z radku dokladu
                 * @param content
                 * @returns
                 */
                function PrevzitCastky(content) {
                    let grid = Gordic.Eko.Grid.getGrid(content.classID); //GetGrid(content);
                    if (grid === null)
                        return $.Deferred().reject().promise();
                    let dtoDateRow = Gordic.Eko.WebClient.Common.GetAllRows(grid);
                    let gridZapisy = Gordic.Eko.Grid.getGrid(content.classIDZapisy); //GetZapisyGrid(content);
                    if (gridZapisy === null)
                        return $.Deferred().reject().promise();
                    var zapisydto = Gordic.Eko.WebClient.Common.GetAllRows(gridZapisy); //gridZapisy.ggrid("getView").getDataRows(false);
                    dtoDateRow.forEach(radekKontace => {
                        let radek = JeRadekVZapisech(radekKontace.radek_z, zapisydto);
                        if (typeof radek !== "undefined") {
                            radekKontace.c0_t = PrevodHodnoty(radek.c0);
                            radekKontace.c1_t = PrevodHodnoty(radek.c1);
                        }
                    });
                    const view = grid.ggrid("getView");
                    view.updateData(dtoDateRow);
                    ChangeValue(content, true);
                    return $.Deferred().resolve().promise();
                    //return EKOUtils.CallRemoteService(content,"PrevzetiCastek", { seznam: dtoDateRow, zapisy: zapisydto }, "Gordic.Eko.WebClient.GDetailPredkontace")
                    //    //return content.call("NastaveniVlastnihoNS", { seznam: content.PredkontaceDto.Zapisy })
                    //    .then(function (seznam) {
                    //        content.PredkontaceDto.Zapisy = seznam;
                    //        var view = new Gordic.Data.View(content.PredkontaceDto.Zapisy || [], { key: "ixs_kon" });
                    //        if (grid === null) return false;
                    //        grid.ggrid("setData", view, true);
                    //        content.showFlash({ id: "flashNastaveniNS", icon: "gi-tick", label: "jres:30250089".format(Gordic.Consts.DbShortcuts.nks), customClass: "g-state-success" }) //RC 30250089 : Částky ze zápisů zkopírovány
                    //        // reaguj na zmenu dat
                    //        ChangeValue(content, true);
                    //        return true;
                    //    });
                }
                DetailPredkontaceMethod.PrevzitCastky = PrevzitCastky;
                /// <summary>
                /// Prevod decimalni hodnoty na hodnotu formatu predkontace
                /// </summary>
                /// <param name="hodnota"></param>
                /// <returns></returns>
                function PrevodHodnoty(hodnota) {
                    if (typeof hodnota === "undefined" || hodnota === null || !parseDecimal(hodnota).cmp(0))
                        return "";
                    else {
                        return "m;0;" + parseDecimal(hodnota).toString().trim().replace(".", ",");
                    }
                }
                /**
                 * Dohledani cislo radku v zapisech
                 * @param cisloRadku
                 * @param zapisy
                 * @returns
                 */
                function JeRadekVZapisech(cisloRadku, zapisy) {
                    var zapis = zapisy.find(radek => (radek.radek_z == cisloRadku));
                    return zapis;
                }
                /**
                 * Vymazat radek
                 * @param content
                 */
                function VymazatRadek(content) {
                    const myGrid = Gordic.Eko.Grid.getGrid(content.classID); //GetGrid(content);
                    //let removeRows = Gordic.Eko.WebClient.Common.OznaceneRadky<Gordic.Eko.Interface.GUctRozskonDto>(myGrid);
                    let removeRows = Gordic.Eko.Grid.checkedRows(myGrid);
                    if (!removeRows || removeRows == null || removeRows.length == 0) {
                        content.dialogs.messageBox("jres:30250075" //RC 30250075 : Info
                        , "jres:30250076"); //RC 30250076 : Nenalezeny označené řádky
                        return;
                    }
                    var msg = "";
                    msg = (removeRows.length == 1) ? "jres:30250077" //RC 30250077 : Opravdu chcete vymazat označený řádek?
                        : "jres:30250078"; //RC 30250078 : Opravdu chcete vymazat označené řádky?
                    content.dialogs.messageBox("jres:30250079", msg, GDlg.mbbYesNo, GDlg.mbiQuestion) //RC 30250079 : Dotaz
                        .on("yes", function () {
                        if (myGrid === null)
                            return;
                        var dtoDateRow = Gordic.Eko.WebClient.Common.GetAllRows(myGrid);
                        removeRows.forEach(function (radek) {
                            dtoDateRow = DeleteRow(dtoDateRow, radek.radek, true);
                        });
                        ReCount(dtoDateRow);
                        content.EditaceZapisu = true;
                        ChangeValue(content, false);
                        // nastaveni dat od gridu - predkontacni radky
                        var view = new Gordic.Data.View(dtoDateRow, { key: "ixs_kon" });
                        myGrid.ggrid("setData", view, true);
                        if (content.ModeDetail === Gordic.Eko.WebClient.UctRoz.Enums.ModeDetail.PrevodZapisu) {
                            // nastavim nevykonavani udalosti
                            content.myLoading = true;
                            // oznaceni checkboxu na seznamu zapisu
                            var gridZapisy = Gordic.Eko.Grid.getGrid(content.classIDZapisy); //GetZapisyGrid(content);
                            if (gridZapisy === null)
                                return;
                            gridZapisy.ggrid("getView").getDataRows(true).forEach(function (meta) {
                                meta.checked = typeof dtoDateRow.find(function (a) {
                                    return a["radek_z"] === meta.data.radek_z;
                                }) !== "undefined";
                            });
                            gridZapisy.ggrid("refreshRows");
                            // povolim udalosti
                            content.myLoading = false;
                        }
                    });
                }
                DetailPredkontaceMethod.VymazatRadek = VymazatRadek;
                /**
                 * function DeleteRow
                 *
                 * @param {any} dataRows
                 * @param {Number} radek_z
                 * @param {boolean} nePrecislovat
                 * @returns {any}
                 */
                function DeleteRow(dataRows, radek, nePrecislovat) {
                    var filtrRows = dataRows.filter(function (a) {
                        if (radek == null) {
                            if (a.radek_z == null || typeof a.radek_z === "undefined")
                                return true;
                            return false;
                        }
                        else
                            return a.radek !== radek;
                    });
                    if (nePrecislovat !== true)
                        // provedu precislovani
                        ReCount(filtrRows);
                    return filtrRows;
                }
                DetailPredkontaceMethod.DeleteRow = DeleteRow;
                /**
                 * Precislovani radku
                 * @param dataRows
                 */
                function ReCount(dataRows) {
                    // precislovani
                    var cisloRadku = 1;
                    dataRows.forEach(function (radek) {
                        radek.radek = cisloRadku;
                        cisloRadku++;
                    });
                }
                DetailPredkontaceMethod.ReCount = ReCount;
                /**
                 * Vytvoreni gridfomatu
                 * @param content
                 */
                function GetPorizovacGridFormat(content) {
                    var myContent = content;
                    var gridFormat = new Gordic.Data.GridFormat();
                    if (content.ModeDetail === Gordic.Eko.WebClient.UctRoz.Enums.ModeDetail.PrevodZapisu) {
                        // cislo ucetniho zapisu
                        gridFormat.addNumberColumn({
                            name: "radek_z",
                            caption: "jres:31750010", //RC 31750010 : #
                            description: "jres:30250092", //RC 30250092 : Číslo účetního zápisu
                            width: 70,
                            customClass: "ui-disabled",
                            sortable: false,
                        });
                    }
                    gridFormat.addNumberColumn({
                        name: "radek",
                        caption: "jres:30250028", //RC 30250028 : Řádek
                        width: 70,
                        customClass: "ui-disabled",
                        sortable: false,
                    });
                    // prevzeti sloupcu    
                    content.PredkontaceDto.EkoCfuModify.columns.forEach(function (sloupec, i) {
                        //    var sloupec = content.PredkontaceDto.EkoCfuModify.columns[i];
                        gridFormat.addTextColumn({
                            name: sloupec.name,
                            caption: sloupec.caption,
                            sortable: false,
                            width: 200,
                            customClass: function (meta, column, rowIndex, colIndex) {
                                var data = meta.data[column.name];
                                if (data && (getActivityText(data, sloupec.wordSequence) === data)) {
                                    return "g-state-background g-state-error";
                                }
                                else
                                    return "";
                            },
                            cellTemplate: function (row) { return elementWithTooltip(row[sloupec.name], sloupec.wordSequence); },
                            editor: {
                                widget: "gselectbox",
                                options: {
                                    name: sloupec.name,
                                    itemTemplate: function (obj) { return obj[sloupec.name]; },
                                    length: 50,
                                    //cellTemplate: function (obj) { obj[sloupec.name] },
                                    disabled: false,
                                    //strict:false,
                                    //model: "model." + sloupec.name + "=value.code",
                                    model: "model." + sloupec.name + "=value." + sloupec.name,
                                    verify: function (a) {
                                        if (typeof a === "string") {
                                            var hodnota = {};
                                            hodnota[sloupec.name] = a;
                                            return hodnota;
                                        }
                                        return a;
                                    },
                                    helperCustomizer: function (data) {
                                        return data;
                                    },
                                    //TODO: toto v optionach neni
                                    //custSmartNav: function (current, nextSmartNavElement) {
                                    //    return nextSmartNavElement;
                                    //},
                                    selector: function (options) {
                                        let def = $.Deferred();
                                        const grid = Gordic.Eko.Grid.getGrid(content.classID); //GetGrid(content);
                                        if (grid === null)
                                            return def.resolve(null);
                                        ;
                                        const gridI = grid.ggrid("instance");
                                        // nemam ev, nelze pouzit
                                        //var field = Gordic.Eko.GPorizovac.Utils.getField(ev.originalEvent.target);
                                        var activeCell = gridI?.activeCellAddress();
                                        if (activeCell?.column == null /*|| activeCell.column?.name == null*/)
                                            return def.resolve(null);
                                        ;
                                        //var dataWord = activeCell!.column!.name;
                                        const { caption: dataWordCaption, name: dataWord } = activeCell.column;
                                        var cellAdrRow = gridI?.activeCellAddress().row;
                                        if (typeof cellAdrRow === "undefined")
                                            return def.resolve(null);
                                        ;
                                        var value = activeCell.data[sloupec.name];
                                        //var napovedaDialog = Napoveda(myContent, sloupec.wordSequence);
                                        //if (napovedaDialog == null) return def.resolve(null);
                                        //debugger;
                                        var dlg = myContent.dialogs.showModalWindow(vyberoveOkno, { typeItem: sloupec.wordSequence, dataWord: dataWord, index: cellAdrRow, model: value ? value : null }, 
                                        //var dlg = myContent.dialogs.showModalWindow(napovedaDialog, { dataWord: dataWord, index: cellAdrRow, model: value ? value : null },
                                        "jres:30250108".format(activeCell?.column?.caption, (cellAdrRow + 1)) //RC 30250108 : Předkontace slova {0} ř. {1}
                                        );
                                        dlg.on("close", function (ev, obj) {
                                            if (obj !== null) {
                                                getStateIcon(obj, grid?.findFields(activeCell.column.name));
                                                if (obj === undefined)
                                                    obj = value;
                                                // pokud o vytvoreni navratoveho objektu
                                                //var hodnota = {};
                                                var hodnota2 = {};
                                                hodnota2[activeCell.column.name] = obj;
                                                //hodnota["value"] = hodnota2;
                                                //activeCell.data[sloupec.name] = obj;
                                                // nemma field, nevim kde ziskat
                                                //field.setValue(objClose ? { code: objClose } : null);
                                                def.resolve(hodnota2);
                                                return;
                                                //field.focus();
                                            }
                                            def.resolve(null);
                                        });
                                        return def.promise();
                                    }
                                }
                            }
                        });
                    });
                    return gridFormat;
                }
                DetailPredkontaceMethod.GetPorizovacGridFormat = GetPorizovacGridFormat;
                /**
                 * Word: Zobrazeni tooltipu s varovanim
                 *
                 * @author Tomáš Kareš
                 * @since 480.1.0.66
                 */
                function elementWithTooltip(code, typeWord) {
                    //            var text = this.getActivityText(code);
                    //          var hodnota =(text === code ? code : "<span class='js-tooltip hinttext' data-title='" + text + "'>" + code + "</span>");
                    //return hodnota;            
                    //if (!code) return "";
                    if (!code)
                        return "";
                    //debugger;
                    var text = getActivityText(code, typeWord);
                    var isValid = text !== code;
                    text = isValid ? text : "jres:30250093"; //RC 30250093 : Vámi zadaná kombinace překontace není platná.
                    return "<span class='js-tooltip hinttext" + (isValid ? "" : " js-errorState") + "' data-title='" + text + "' title='" + text + "'>" + code + "</span>";
                }
                /**
                 * Tektovy popis policka
                 *
                 * @author Tomáš Kareš
                 * @since 480.1.0.66
                 */
                function getActivityText(modelStr, typeWord) {
                    if (!modelStr || modelStr.indexOf(";") === -1)
                        return modelStr;
                    var model = modelStr.split(";");
                    var activityStr = "";
                    switch (model[0]) {
                        case "n":
                            activityStr = "jres:30250094"; //RC 30250094 : Přednastavené NS
                            break;
                        case "N":
                            activityStr = "jres:30250099"; //RC 30250099 : Vlastní NS
                            break;
                        case "b":
                            activityStr = "jres:30250095"; //RC 30250095 : Dopočtena vyrovnávací částka
                            break;
                        case "X":
                            activityStr = "jres:30250096"; //RC 30250096 : Hodnota z hlavičky
                            break;
                        case "x":
                            activityStr = "jres:30250097"; //RC 30250097 : Hodnota z hlavičky s opačným znaménkem
                            break;
                        case "C":
                            activityStr = "jres:30250098"; //RC 30250098 : Hodnota z předcházejícího řádku z opačné strany
                            break;
                        //case "D":
                        //    activityStr = "Hodnota z předcházejícího řádku z opačné strany s opačným znaménkem";
                        //    break;
                        //case "d":
                        //    activityStr = "Hodnota z předchazejícího řádku s opačným znaménkem";
                        case "h":
                            activityStr = "Nápověda" + (model[2] != null && model[2].trim() !== "" ? " s předvyplněnou hodnotou " + model[2] : "");
                            break;
                        case "m":
                            activityStr = "jres:30250274"; //+ (model[2] != null ? " " + model[2] : ""); //RC 30250274 : Hodnota
                            if (typeWord === Gordic.Eko.WebClient.UctRoz.Enums.TypPolicka.Smlouva) {
                                if (model[2] != null) {
                                    var smlouva = model[2].split("#");
                                    activityStr += " " + "jres:30250275".format(smlouva[0]); //RC 30250275 : PID sml.= {0}
                                    if (smlouva.length > 1)
                                        activityStr += " , " + "jres:30250276".format(smlouva[1]); //RC 30250276 : č. řádku sml.= {0}
                                }
                            }
                            else
                                activityStr += (model[2] != null ? " " + model[2] : "");
                            break;
                        case "C":
                        case "V":
                            activityStr = "jres:30250273".format(model[2]); //RC 30250273 : Kopie z ř. {0} z opačné strany
                            break;
                        case "d":
                            activityStr = "jres:30250270"; //RC 30250270 : Kopie z předcházejícího řádku s opačným znaménkem
                            break;
                        case "w":
                            activityStr = "jres:30250272".format(model[2]); //RC 30250272 : Kopie z ř. {0} s opačným znaménkem
                            break;
                        case "D":
                            activityStr = "jres:30250269"; //RC 30250269 : Kopie z předcházejícího řádku z opačné strany s opačným znaménkem
                            break;
                        case "W":
                            activityStr = "jres:30250271".format(model[2]); //RC 30250271 : Kopie z ř. {0} z opačné strany s opačným znaménkem
                            break;
                        case "v":
                            activityStr = "jres:30250267".format(model[2]); //RC 30250267 : Kopie z ř. {0}
                            break;
                        case "0":
                            activityStr = "jres:30250266"; //RC 30250266 : Žádná činnost
                            break;
                        case "c":
                            activityStr = "jres:30250265"; //RC 30250265 : Kopie z předcházejícího řádku
                            break;
                        case "p":
                            activityStr = "jres:30250264"; //RC 30250264 : Kopie SU z předcházejícího řádku
                            break;
                        case "e":
                            activityStr = "jres:30250268".format(model[2]); //RC 30250268 : Kopie SU z ř. {0}
                            break;
                        default:
                            return modelStr;
                        //activityStr = "Nic";
                    }
                    activityStr = (model[1] === "0"
                        ? activityStr + "jres:30250263" //RC 30250263 :  a skok
                        : model[1] === "w" ?
                            activityStr + "jres:30250262" //RC 30250262 :  a čekání
                            : modelStr);
                    return activityStr;
                    //            activityStr += (model[1] === "0" ? " a skok" : " a čekání");
                }
                /**
                 * Nastaveni stavove ikony
                 *
                 * @param {any} value
                 * @param {any} field
                 */
                function getStateIcon(value, field) {
                    if (!value) {
                        field.gfield("getState", "tooltipState").remove();
                        return;
                    }
                    var tooltip = getActivityText(value, Gordic.Eko.WebClient.UctRoz.Enums.TypPolicka.EKO);
                    if (tooltip !== value) {
                        var icon = field.gfield("getState", "tooltipState");
                        if (icon.length === 0) {
                            field.gfield("addState", {
                                id: "tooltipState", // nepovinný, pouze pokud bude potřeba ikonu adresovat/měnit
                                icon: "fa-info-circle",
                                customClass: "g-state-info",
                                tooltip: tooltip,
                                tooltipPosition: { at: "left top", collision: "flipfit flip", my: "left bottom" }
                            });
                        }
                        else {
                            icon.gtooltip("option", "tooltip", tooltip);
                        }
                    }
                }
