/**
 * Akce na zapnutí/vypnutí expertního režimu v EKO modulech
 *
 * @author Petr Vošta
 * @since 525.3
 */
var Gordic;
(function (Gordic) {
    var Eko;
    (function (Eko) {
        var Action;
        (function (Action) {
            /**
             * Definice parametrů pro akci zapnutí/vypnutí expertního režimu
             *
             * @param {GContent} content content, na kterém bude tlačítko Expertní režim (většinou this)
             * @param {number} levelExp úroveň expertního režimu
            * * @param {Function} onCloseExpertMode funkce, která se zavolá po vypnutí expertního režimu
             * @param {GActionParamsDefObjBase} params další parametry akce
             * @returns {GActionParamsDefObj} výsledné parametry akce expertního režimu
             */
            function actionExpertMode(content, levelExp, onSetExpertMode, onCloseExpertMode, params) {
                const actExpertMode = new GAction($.extend(true, {
                    name: "actExpertMode",
                    caption: "Expertní režim", // RC 29750107 : Aktivní
                    icon: "gi-lock", // ikona
                    //enabled: urovenPristupu === 40,                                                                                      // vždy viditelné
                    //enabled: this.hlavniSpravce,                                                                                      // vždy spustitelné
                    checked: false,
                    run: function () {
                        if (this.checked() == false)
                            setExpertMode(content, levelExp, this, onSetExpertMode);
                        else
                            closeExpertMode(content, this, onCloseExpertMode);
                    }
                }, params));
                return actExpertMode;
            }
            Action.actionExpertMode = actionExpertMode;
            function setExpertMode(content, levelExp, action, onSetExpertMode) {
                //const that = this;
                //const act = that.actions.actExpertMode!;
                const def = $.Deferred();
                return Gordic.Gui.Dialogs.GExpertModeDlg({ parentContent: content, opt: { levelExp: levelExp }, ModOtevreni: Gordic.Global.Enums.ModOtevreni.showModalWindow }).then((o) => {
                    if (o) {
                        const srvCnt = content.createServiceContent("Gordic.Eko.WebClient.GExpertModeActionContent");
                        srvCnt.call("expertModeOpened", { ixxKey: o.ixxKey })
                            .then((expertModeOpened) => {
                            if (expertModeOpened) {
                                action.checked(true);
                                action.update({
                                    //caption: !act.checked() ? "Editace povolena" : "Uzamčeno",
                                    icon: "gi-tick",
                                });
                                //onSetExpertMode(content);....to by muselo mít na vstupu content, protože by tam nefungovalo this
                                onSetExpertMode.call(content);
                                //that.expertMode = true;
                                //that.enabledTlacitek(true);
                                return def.resolve(true).promise();
                            }
                            else {
                                content.dialogs.alert("Zadán chybný ověřovací kód");
                                return def.resolve(false).promise();
                            }
                        }, () => {
                            content.dialogs.alert("Ověřování kódu pro expertní režim skončilo chybou");
                            return def.resolve(false).promise();
                        })
                            .always(() => { srvCnt.close(); });
                    }
                    else {
                        return def.resolve(false).promise();
                    }
                });
            }
            function closeExpertMode(content, action, onCloseExpertMode) {
                const srvCnt = content.createServiceContent("Gordic.Eko.WebClient.GExpertModeActionContent");
                srvCnt.call("closeExpertMode").then(() => {
                    action.checked(false);
                    action.update({
                        //caption: !act.checked() ? "Editace povolena" : "Uzamčeno",
                        icon: "gi-lock",
                    });
                    //onCloseExpertMode(content);
                    onCloseExpertMode.call(content);
                    //that.expertMode = false;
                    //that.enabledTlacitek(false);
                })
                    .always(() => { srvCnt.close(); });
            }
        })(Action = Eko.Action || (Eko.Action = {}));
    })(Eko = Gordic.Eko || (Gordic.Eko = {}));
})(Gordic || (Gordic = {}));
