                                        r.data.cc_2_3_7_8_23_25_14_34_54 = parseDecimal(r.data.c_2_3_7_8_23_25_14_34_54).abs();
                                        r.data.cc_c_6_18 = parseDecimal(r.data.c_6_18).abs();
                                        r.data.cc_c_10_11 = parseDecimal(r.data.c_10_11).abs();
                                        r.data.cc_c_15_16_17 = parseDecimal(r.data.c_15_16_17).abs();
                                        r.data.c_zbyva_nasmlouvat = parseDecimal(r.data.c_kc).abs().minus((parseDecimal(r.data.c_10_11).plus(parseDecimal(r.data.c_15)).plus(parseDecimal(r.data.c_17)).plus(parseDecimal(r.data.c_6))).abs());
                                        r.data.c_zbyva_cerpat = parseDecimal(r.data.c_kc).abs().minus(parseDecimal(r.data.c_0).abs());
                                        r.data.c_nenasmlouvano_z_roz = parseDecimal(r.data.c_kc).abs().minus(parseDecimal(r.data.c_12).abs()).minus(parseDecimal(r.data.c_10).abs()).minus(parseDecimal(r.data.c_15).abs()).minus(parseDecimal(r.data.c_6).abs());
                                        r.data.c_nenasmlouvano_z_blk = parseDecimal(r.data.c_12).abs().minus(parseDecimal(r.data.c_11).abs()).minus(parseDecimal(r.data.c_17).abs());
                                        r.data.c_neobjednano_z_sml = parseDecimal(r.data.c_10).abs().plus(parseDecimal(r.data.c_11).abs()).minus(parseDecimal(r.data.c_16).abs()).minus(parseDecimal(r.data.c_18).abs());
