            const drdDataCache = { initialized: false };
            function drdInit() {
                if (drdDataCache.initialized)
                    return;
                const uctDef = $.Deferred();
                const rozDef = $.Deferred();
                const ostDef = $.Deferred();
                drdDataCache.drd_ucetnictvi = uctDef.promise();
                drdDataCache.drd_rozpocet = rozDef.promise();
                drdDataCache.drd_ostatni = ostDef.promise();
                new Gordic.Data.Readers.Ekocdrd().provider()().done(function (view) {
                    var data;
                    if (view instanceof Gordic.Data.View)
                        data = view.getRows();
                    else if (view instanceof Array)
                        data = view;
                    else
                        throw new Error("Gordic.Eko.Filters.drdInit(): argument is not supported.");
                    var rows = data.filter(function (d) { return d.drd < 100; });
                    uctDef.resolve(rows.filter(function (d) { return d.priz_ur_ses === 0; }));
                    rozDef.resolve(rows.filter(function (d) { return d.priz_ur_ses === 10 || d.priz_ur_ses === 14; }));
                    ostDef.resolve(rows.filter(function (d) { return d.priz_ur_ses !== 0 && d.priz_ur_ses !== 10 && d.priz_ur_ses !== 14; }));
                });
            }
            //#endregion
            //#region Shared functions
            function multiSelectChange(ev, value, otherMultiSelectName) {
                ///<param name='otherMultiSelectName' type='Array'>Nazev druheho policka pro dohledani vybranych hodnot</param>
                var $drdForm = $(this).gform();
                if ($drdForm.hasClass("js-drd-changing"))
                    return;
                $drdForm.addClass("js-drd-changing");
                var arr = new Array();
                otherMultiSelectName.forEach(function (fieldName) {
                    var $field = $drdForm.findFields(fieldName);
                    if ($field.length === 0)
                        return;
                    var val = $field.gfield("getValue");
                    if (val)
                        arr = arr.concat(val);
                });
                arr = arr.concat(value);
                var s = arr.map(function (v) { return v.drd; })
                    .sort(function (a, b) { return Number(a) - Number(b); })
                    .join(",");
                $drdForm.findFields("drd").gfield("clear").gfield("setValue", s);
                $drdForm.removeClass("js-drd-changing");
            }
