                    var cell; //pomocné proměnné pro cell execute
                    var data;
                    //var my_CondFormat: Gordic.Components.Grid.CondFormats.CondFormat = { description: "Schváleno", formula: "IF(NOT(ISBLANK(@up_stav)) and (@up_stav == 20), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.green };
                    //var my_CondFormatDoplnkovyRadek: Gordic.Components.Grid.CondFormats.CondFormat = { description: "Doplňkový řádek", formula: "IF(NOT(ISBLANK(@ktg_lik)) and (@ktg_lik == 1), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.yellow };
                    //var my_CondFormats: Gordic.Components.Grid.CondFormats.CondFormat[] = [];
                    //my_CondFormats.push(my_CondFormat);
                    //my_CondFormats.push(my_CondFormatDoplnkovyRadek);
                    let dWords = ["uea", "ueb", "uec", "ued", "uee", "uef", "ueg", "ueh", "uei", "uej", "te0", "te1", "te2", "te3", "te4", "uek", "uel", "uem", "uen", "te5", "te6", "te7", "te8", "te9"];
                    let columnList = that.gridFormat.columns.map(e => e.name).join(',');
