                Common.ZobrazeniHlasky = ZobrazeniHlasky;
                /**
                 * Zpracovani zpravy
                 * @param {GContent} content
                 * @param {any} zprava
                 * @returns
                 */
                function ZpracovaniZpravy(content, zprava, externProcessed, object) {
                    var def = $.Deferred();
                    if (zprava.TypeMessage === 100 /* Gordic.Eko.Interface.GETypeTransferMessage.UserMessage */) {
                        if (externProcessed !== null && typeof externProcessed !== "undefined") {
                            // volani externiho zpracovani
                            externProcessed(content, zprava, def, object)
                                .then((retvalue) => {
                                return def.resolve(retvalue);
                            });
                        }
                        // pridano 5.9.2019 otestovat, zda to nekde nebude delat problem
                        else
                            return def.resolve(zprava);
                    }
                    else {
                        ZobrazeniHlasky(content, zprava, object)
                            .then(function (param) {
                            return def.resolve(param);
                        });
                    }
                    return def.promise();
                }
                Common.ZpracovaniZpravy = ZpracovaniZpravy;
                /**
                 * Zobrazeni ulozeneho reportu (stazeni ulozeneho souboru)
                 * @param {GContent} content
                 * @param {any} reportFile
                 * @param {any} myParam
                 */
                function ShowReportForm(content, reportFile, myParam, object) {
                    var form = new Gordic.Forms.Form("L1M1S1, L-12-12-0, M-12-12-0, S-12-12-0")
                        .addField("gstatic", {
                        caption: "jres:23352022" //RC 23352022 : Stažení sestavy pro možnost zobrazení
                    });
                    var def = $.Deferred();
                    var simpleForm = content.dialogs.simpleForm("jres:23352020", form, {}, $.extend({}, {
                        width: 500, height: 160, related: object?.relatedElement,
                        commandBar: [
                            {
                                customClass: "g-button--primary",
                                action: new GAction({
                                    name: "actDownload", caption: "jres:23352021", icon: "gi-download" //RC 23352021 : Stažení sestavy
                                    ,
                                    run: function (ev) {
                                        return DownloadReport(simpleForm.gcontent(), reportFile);
                                    }
                                })
                            },
                            {
                                action: new GAction({
                                    name: "actZrusit", caption: GDlg.mbbCancel.text, icon: "gi-window-close", run: function (ev) {
                                        simpleForm.gcontent().close();
                                    }
                                })
                            }
                        ]
                    }));
                    simpleForm.on({
                        close: function (ev, data) {
                            return def.resolve(myParam);
                        }
                    });
                    return def.promise();
                }
                Common.ShowReportForm = ShowReportForm;
                /**
                 * Zobrazeni/ generovani reportu
                 * @param {GContent} content
                 * @param {any} myParam
                 * @returns
                 */
                function ZobrazReport(content, myParam, object) {
                    let repParam = myParam; // myParam.ReportParam;
                    if (myParam.ReportParam)
                        repParam = myParam.ReportParam;
                    if (repParam.ReportFile && repParam.ReportFile != "") {
                        return ShowReportForm(content, repParam.ReportFile, myParam, object);
                    }
                    var def = $.Deferred();
                    var tisk = GAction.createPrintAction({
                        name: "actPrintXX",
                        caption: repParam.Caption,
                        parentContent: content,
                        tema: repParam.Thema, //nazev tematu
                        //platnost: print.Platnost,
                        serverParameterMethod: repParam.ServerParameterMethod, //"Gordic.Uct.WebClient.GUctPrintParameters:ServerParameterMethodTiskAgendDokladu",
                        serverRestrictionAlvMethod: repParam.ServerRestrictionAlvMethod,
                        enabled: true,
                        //favorite: false,
                        initFavorites: repParam.UseFavorits,
                        selectReportOnly: !repParam.Print,
                        reportGenerated: function (event, retVal) {
                            //debugger;
                        },
                        //reportGeneratorType: "Gordic.Uct.WebClient.GUserGenerator",
                        dialogClosed: function (event, retVal) {
                            //type RepDataDto = { souvisejici?: RepSouvisejiciDataDto[] };
                            if (!retVal) {
                                if (typeof myParam.Result !== "undefined")
                                    myParam.Result = 20 /* Gordic.Eko.Interface.GEResultOfProcessingTheMessage.Error */;
                                return def.resolve(myParam);
                            }
                            if (!repParam.Print) {
                                var params = {
                                    X0000: repParam.Par0,
                                    X0001: repParam.Par1,
                                    X0002: repParam.Par2,
                                    X0003: repParam.Par3,
                                    X0004: repParam.Par4,
                                    X0005: repParam.Par5,
                                    X0006: repParam.Par6,
                                    X0007: repParam.Par7,
                                    X0008: repParam.Par8,
                                    X0009: repParam.Par9,
                                    IXP: repParam.IXP
                                };
                                const cancellationToken = new GObservableObject({
                                    cancelled: false,
                                    uniqueClass: ""
                                });
                                //var cancellationToken = { cancel: false };
                                const cancelAct = new GAction({
                                    name: "repGenCancelAct",
                                    caption: "jres:30250297", //RC 30250297 : Storno
                                    enabled: true,
                                    visible: true,
                                    run: function () {
                                        //cancellationToken.cancel = true;
                                        cancellationToken.update({ cancelled: true });
                                        this.update({
                                            caption: "jres:30250296", //RC 30250296 : Stornuji
                                            enabled: false
                                        });
                                    }
                                });
                                const genCnt = content.createServiceContent([Gordic.Report.WebClient.GReportAsyncGenerator, {}]);
                                genCnt.on("progress", (progress) => {
                                    //NOTE: nativni promise nema progress, budeme resit pres udalost
                                    content.progressOperation({
                                        text: Gordic.Report.WebClient.GReportTreeControlTS.formatProgressMessage(progress.text),
                                        progress: progress.current,
                                        total: progress.total,
                                        cancelAction: cancelAct
                                    });
                                });
                                genCnt.readyAwait.then(() => {
                                    return genCnt.generate({
                                        reportId: retVal?.reportId,
                                        platnost: repParam.Platnost,
                                        params: params
                                    }, cancellationToken); //Samotne generovani
                                })
                                    //generator.generate({
                                    //    reportId: retVal?.reportId!, platnost: repParam.Platnost!, params: params as any
                                    //}, null, cancellationToken)
                                    //    .progress(function (progress) {
                                    //        Gordic.Report.WebClient.GReportGenerator.progressUpdate(content, progress);
                                    //    })
                                    .then((data) => {
                                    content.endOperation();
                                    /*genCnt.clear(data);*/ //TODO (BM): Toto se musi nekde zavolat!!!
                                    return def.resolve(myParam);
                                }).catch(function (state) {
                                    content.endOperation();
                                    myParam.Result = 20 /* Gordic.Eko.Interface.GEResultOfProcessingTheMessage.Error */;
                                    if (state && $.isPlainObject(state) && state.state === -2) { //-2 = generovani zruseno uzivatelem
                                        content.showFlash({
                                            label: "jres:30250106", //RC 30250106 : Generování sestavy bylo zrušeno
                                            customClass: "g-state-warning"
                                        });
                                    }
                                    else if (state.genState && state.genState === "exception") {
                                        throw new GServerError(state.exception);
                                    }
                                    return def.resolve(myParam);
                                }).always(() => { genCnt.close(); });
                            }
                            else
                                def.resolve(myParam);
                        },
                        reportStarting: function (rep) {
                            rep.params.X0000 = repParam.Par0;
                            rep.params.X0001 = repParam.Par1;
                            rep.params.X0002 = repParam.Par2;
                            rep.params.X0003 = repParam.Par3;
                            rep.params.X0004 = repParam.Par4;
                            rep.params.X0005 = repParam.Par5;
                            rep.params.X0006 = repParam.Par6;
                            rep.params.X0007 = repParam.Par7;
                            rep.params.X0008 = repParam.Par8;
                            rep.params.X0009 = repParam.Par9;
                            rep.params.IXP = repParam.IXP;
                            //debugger;
                        }
                    });
                    //repParam.ReportDTO
                    if (repParam.Platnost != "")
                        tisk.platnost = repParam.Platnost;
                    /*tisk.on("dialogClosed", function (event, retVal) {
                    def.reject(parametr);
                    
                    });*/
                    tisk.run();
                    return def.promise();
                }
                Common.ZobrazReport = ZobrazReport;
