                /**
                 * Stazeni ulozeneho reportu
                 * @param {GContent} content
                 * @param {any} reportFile
                 * @returns
                 */
                function DownloadReport(content, reportFile) {
                    var doc = new GDocument(content);
                    return doc.downloadDocument({ DownloaderType: "Gordic.Eko.WebClient.GReportDownloader", CustomData: { filePath: reportFile } });
                }
                Common.DownloadReport = DownloadReport;
                /**
                 * Ze vstupniho objektu se vraci pole zprav, nebo null
                 * @param {any} entry
                 * @returns
                 */
